"use client";

import Orb from "./ai-orb-face-orb";
import { cn } from "@/lib/utils";
import {
  type MotionValue,
  motion,
  useAnimationControls,
  useReducedMotion,
  useSpring,
} from "motion/react";
import { useCallback, useEffect, useRef, useState } from "react";
import { EASE_LINEAR } from "./ai-orb-face-animation";
import {
  type AIAmplitude,
  type AIState,
  getAIStateMotion,
  useAmplitudeValue,
} from "./ai-orb-face-core";

const VIEWBOX = 100;
const CENTER = VIEWBOX / 2;
const EYE_OFFSET = 16;
const EYE_Y = 44;
const EYE_WIDTH = 11;
const EYE_HEIGHT = 26;
const EYE_RADIUS = 5.5;
/** How far the pupils can travel from centre, in viewBox units. */
const GAZE_RANGE = 5.5;
/** Cursor distance, in px, at which the gaze reaches full deflection. */
const GAZE_FALLOFF = 220;
const EASE_OUT = [0.23, 1, 0.32, 1] as const;
const EASE_IN = [0.4, 0, 1, 1] as const;
/** A ~1.25-turn swirl; spun in place it reads as dizzy. */
const SPIRAL = "M0 0C-0.6 -4 5 -5 6 -0.6C7 4.5 1 8 -4 6C-9 4.5 -9.5 -2 -6 -6";
const BLINK_MIN_MS = 3200;
const BLINK_EXTRA_MS = 2600;
const DOUBLE_BLINK_CHANCE = 0.25;
/** Thinking saccades: the eyes look away and up, the way people search. */
const SACCADE_MIN_MS = 700;
const SACCADE_EXTRA_MS = 700;
const SACCADE_TARGETS = [
  { x: -1, y: -1 },
  { x: 1, y: -1 },
  { x: -0.6, y: -0.4 },
  { x: 0.8, y: -0.9 },
] as const;

/** Orb draws its sphere at this fraction of its box; the rest is glow room. */
const ORB_SPHERE_FRACTION = 0.86;

/** Amplitude buckets. Five steps is enough to see the interior stir. */
const ENERGY_STEPS = 4;

/**
 * Amplitude as React state, quantised.
 *
 * Orb takes plain props, so the level has to cross into a render, and a motion
 * value changes every frame, which would re-render the whole character sixty
 * times a second to nudge one uniform. Rounding to a handful of buckets keeps
 * the reaction visible while the component renders a few times per utterance.
 */
const useEnergyBucket = (value: MotionValue<number>) => {
  const [bucket, setBucket] = useState(0);
  useEffect(() => {
    const read = (level: number) =>
      setBucket(Math.round(level * ENERGY_STEPS) / ENERGY_STEPS);
    read(value.get());
    return value.on("change", read);
  }, [value]);
  return bucket;
};

/**
 * An expression is two eyes, and an eye is a rounded capsule.
 *
 * Four numbers describe every face this character can pull: how tall the
 * capsule is, how wide, how far it is rotated, and how far it sits from its
 * resting line. Tall and narrow is neutral; short and wide is a closed, content
 * eye; small is surprise; rotated inward is a scowl. Letting the two eyes carry
 * different values is what buys wink, doubt and mischief for free.
 *
 * There is no mouth. A drawn mouth on a shader body reads as a sticker stuck
 * onto it, and eyes alone are both more legible and more expressive, which is
 * why every avatar system built this way ends up eyes-only.
 */
export interface EyeShape {
  /** Vertical offset in viewBox units. Negative sits the eye higher. */
  dy?: number;
  /** Multiplier on the resting height. `0` is a shut eye. */
  h: number;
  /** Degrees. Positive tilts the inner corner down, which reads as a scowl. */
  rotate?: number;
  /** Multiplier on the resting width. */
  w: number;
}

export interface Expression {
  left: EyeShape;
  right: EyeShape;
}

const EYE = (h: number, w = 1, rotate = 0, dy = 0): EyeShape => ({
  dy,
  h,
  rotate,
  w,
});

/** Mirrored: the same tilt on both eyes, pointing at each other. */
const symmetric = (h: number, w = 1, rotate = 0, dy = 0): Expression => ({
  left: EYE(h, w, rotate, dy),
  right: EYE(h, w, -rotate, dy),
});

export const EXPRESSIONS = {
  /** Wide. Paying attention. */
  alert: symmetric(1.2, 1.05, 0, -1),
  /** Eyes shut, curved down. Reads as content rather than asleep. */
  content: symmetric(0.16, 1.25, 0, 2),
  /** Both eyes tilted inward. */
  cross: symmetric(0.85, 1, 18),
  /** Flat dashes. Unimpressed. */
  deadpan: symmetric(0.14, 1.35),
  /** One eye narrowed. The face is not convinced. */
  doubtful: { left: EYE(1, 1), right: EYE(0.45, 1.1, -14) },
  /** Narrowed and level. Working on it. */
  focused: symmetric(0.55, 1.05),
  /** Resting. */
  neutral: symmetric(1),
  /** Small and high. Caught off guard. */
  surprised: symmetric(0.5, 0.55, 0, -3),
  /** One shut, one open. */
  wink: { left: EYE(1, 1), right: EYE(0.12, 1.2, 0, 2) },
} satisfies Record<string, Expression>;

export type ExpressionName = keyof typeof EXPRESSIONS;

/**
 * The `state` prop keeps working; it now selects an expression instead of
 * branching into a bespoke pair of shapes per state.
 */
const STATE_EXPRESSION: Record<string, ExpressionName> = {
  done: "content",
  error: "cross",
  idle: "neutral",
  listening: "alert",
  streaming: "focused",
  thinking: "doubtful",
};

export type AIOrbFaceProps = {
  /** Accessible label. Omit to keep the character decorative. */
  "aria-label"?: string;
  /** Live audio level, 0–1. Widens the eyes and lifts the body while speaking. */
  amplitude?: AIAmplitude;
  className?: string;
  colors?: { body?: string; bodyEdge?: string; feature?: string };
  /**
   * Follow the pointer with its gaze. Turn off inside dense UI where a dozen
   * of these tracking the cursor would be noise.
   */
  gaze?: boolean;
  /** Rendered size. Numbers are pixels. */
  size?: number | string;
  state?: AIState;
  /**
   * Set the face directly, ignoring `state`. Either a name from
   * `EXPRESSIONS` or a pair of eye shapes of your own.
   */
  expression?: ExpressionName | Expression;
};

/**
 * The two stops now feed Orb's palette rather than a two-stop gradient, and a
 * palette needs range. The previous pair sat within eight points of lightness
 * of each other, so the marbled interior had nothing to marble between and read
 * as flat lilac. Saturated against near-white is what makes the flow visible.
 */
const DEFAULT_COLORS = {
  body: "oklch(72% 0.21 322)",
  bodyEdge: "oklch(97% 0.02 322)",
  feature: "oklch(24% 0.03 280)",
};

/**
 * A little character rather than an indicator.
 *
 * Status is carried by expression: the thing humans read fastest and the reason
 * a literal checkmark stuck onto an orb feels wrong. Squints while it thinks,
 * eyes wide while it listens, happy arcs when it finishes, spiral-eyed when it
 * breaks. The gaze and blink cadence are borrowed from the SmoothUI moai so the
 * two feel like the same creature.
 */
const AIOrbFace = ({
  "aria-label": ariaLabel,
  amplitude,
  className,
  colors,
  gaze = true,
  expression,
  size = 128,
  state = "idle",
}: AIOrbFaceProps) => {
  const shouldReduceMotion = useReducedMotion();
  const amplitudeValue = useAmplitudeValue(amplitude);
  const stateMotion = getAIStateMotion(state);
  const finalColors = { ...DEFAULT_COLORS, ...colors };

  // Gradient ids must be unique per instance, or a second face on the page
  // silently repaints the first one's body.
  const svgRef = useRef<SVGSVGElement | null>(null);
  const energy = useEnergyBucket(amplitudeValue);
  const leftLid = useAnimationControls();
  const rightLid = useAnimationControls();
  const bodyControls = useAnimationControls();

  const gazeX = useSpring(0, { damping: 26, stiffness: 220 });
  const gazeY = useSpring(0, { damping: 26, stiffness: 220 });

  const resolvedSize = typeof size === "number" ? `${size}px` : size;

  const isHappy = state === "done";
  const isThinking = state === "thinking";
  const isListening = state === "listening";
  const isBroken = state === "error";
  const eyesOpen = !isBroken;

  /**
   * Explicit `expression` wins; otherwise the state picks one. A caller can
   * also pass a pair of eye shapes that is not in the preset list at all.
   */
  const active: Expression = (() => {
    if (typeof expression === "object") {
      return expression;
    }
    if (expression) {
      return EXPRESSIONS[expression];
    }
    return EXPRESSIONS[STATE_EXPRESSION[state] ?? "neutral"];
  })();

  // A blink spans several awaits, so the component can unmount mid-blink: a
  // route change, a state that hides the eyes. Animation controls throw if they
  // are driven after unmount, so every leg checks first.
  const mountedRef = useRef(false);
  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
    };
  }, []);

  // Snap shut, ease back open: an even-timed blink reads as a machine.
  const blink = useCallback(
    async (double = false) => {
      const closeT = { duration: 0.07, ease: EASE_IN };
      const openT = { duration: 0.16, ease: EASE_OUT };
      if (!mountedRef.current) {
        return;
      }
      await Promise.all([
        leftLid.start({ scaleY: 0.08 }, closeT),
        rightLid.start({ scaleY: 0.08 }, closeT),
      ]);
      if (!mountedRef.current) {
        return;
      }
      await Promise.all([
        leftLid.start({ scaleY: 1 }, double ? closeT : openT),
        rightLid.start({ scaleY: 1 }, double ? closeT : openT),
      ]);
      if (double) {
        await blink(false);
      }
    },
    [leftLid, rightLid]
  );

  // Idle blinking, occasionally a double.
  useEffect(() => {
    if (shouldReduceMotion || !eyesOpen) {
      return;
    }
    let timeout: ReturnType<typeof setTimeout>;
    let mounted = true;
    const schedule = () => {
      timeout = setTimeout(
        () => {
          if (mounted) {
            blink(Math.random() < DOUBLE_BLINK_CHANCE);
          }
          schedule();
        },
        BLINK_MIN_MS + Math.random() * BLINK_EXTRA_MS
      );
    };
    schedule();
    return () => {
      mounted = false;
      clearTimeout(timeout);
    };
  }, [blink, eyesOpen, shouldReduceMotion]);

  // Gaze follows the pointer, except while thinking, then it looks away, which
  // is exactly what makes "thinking" legible without any added graphic.
  useEffect(() => {
    if (!gaze || shouldReduceMotion || isThinking || !eyesOpen) {
      return;
    }
    const handle = (event: PointerEvent) => {
      const svg = svgRef.current;
      if (!svg) {
        return;
      }
      const rect = svg.getBoundingClientRect();
      const dx = event.clientX - (rect.left + rect.width / 2);
      const dy = event.clientY - (rect.top + rect.height / 2);
      const distance = Math.sqrt(dx * dx + dy * dy);
      const reach = Math.min(1, distance / GAZE_FALLOFF) * GAZE_RANGE;
      const angle = Math.atan2(dy, dx);
      gazeX.set(Math.cos(angle) * reach);
      gazeY.set(Math.sin(angle) * reach);
    };
    window.addEventListener("pointermove", handle);
    return () => window.removeEventListener("pointermove", handle);
  }, [gaze, gazeX, gazeY, isThinking, eyesOpen, shouldReduceMotion]);

  // Thinking saccades.
  useEffect(() => {
    if (!isThinking || shouldReduceMotion) {
      return;
    }
    let timeout: ReturnType<typeof setTimeout>;
    let mounted = true;
    let index = 0;
    const schedule = () => {
      timeout = setTimeout(
        () => {
          if (!mounted) {
            return;
          }
          const target = SACCADE_TARGETS[index % SACCADE_TARGETS.length];
          index += 1;
          gazeX.set(target.x * GAZE_RANGE);
          gazeY.set(target.y * GAZE_RANGE);
          schedule();
        },
        SACCADE_MIN_MS + Math.random() * SACCADE_EXTRA_MS
      );
    };
    schedule();
    return () => {
      mounted = false;
      clearTimeout(timeout);
    };
  }, [gazeX, gazeY, isThinking, shouldReduceMotion]);

  // Error: one dizzy wobble.
  useEffect(() => {
    if (!isBroken) {
      return;
    }
    gazeX.set(0);
    gazeY.set(0);
    if (shouldReduceMotion) {
      return;
    }
    // The wobble plays once, but the spiral eyes stay for as long as the state
    // is `error`. Recovering to a neutral face after a couple of seconds would
    // leave a broken assistant looking fine.
    bodyControls.start(
      { rotate: [0, -11, 9, -7, 5, -3, 0], x: [0, -5, 4, -3, 2, -1, 0] },
      { duration: 1.05, ease: [0.45, 0, 0.55, 1] }
    );
  }, [bodyControls, gazeX, gazeY, isBroken, shouldReduceMotion]);

  // Done: a happy hop. The squash-and-stretch is the whole payload.
  useEffect(() => {
    if (!isHappy || shouldReduceMotion) {
      return;
    }
    bodyControls.start(
      {
        scaleX: [1, 1.08, 0.94, 1.04, 0.99, 1],
        scaleY: [1, 0.9, 1.08, 0.95, 1.02, 1],
        y: [0, 3, -9, 0, -3, 0],
      },
      { duration: 0.85, ease: EASE_OUT, times: [0, 0.12, 0.4, 0.62, 0.82, 1] }
    );
  }, [bodyControls, isHappy, shouldReduceMotion]);

  // Listening: the body breathes with the voice. Driven from the MotionValue so
  // a 60fps audio signal never re-renders this component.
  useEffect(() => {
    if (shouldReduceMotion || !isListening) {
      return;
    }
    const unsubscribe = amplitudeValue.on("change", (level) => {
      bodyControls.set({ scale: 1 + level * 0.07, y: -level * 2 });
    });
    return unsubscribe;
  }, [amplitudeValue, bodyControls, isListening, shouldReduceMotion]);

  // Reset the breathing here rather than in the effect above. Animation
  // controls reject `set()` after unmount, and an unsubscribe cleanup is
  // exactly when the component may already be gone.
  useEffect(() => {
    if (!(isListening || !mountedRef.current)) {
      bodyControls.set({ scale: 1, y: 0 });
    }
  }, [bodyControls, isListening]);

  const renderEye = (side: -1 | 1) => {
    const shape = side === -1 ? active.left : active.right;
    const controls = side === -1 ? leftLid : rightLid;

    const width = EYE_WIDTH * shape.w;
    const height = EYE_HEIGHT * shape.h;
    const x = CENTER + side * EYE_OFFSET - width / 2;
    // Keep the eye centred as it opens and closes, so a squint reads as lids
    // meeting rather than the eye sliding up the face.
    const y = EYE_Y + (EYE_HEIGHT - height) / 2 + (shape.dy ?? 0);
    const cx = x + width / 2;
    const cy = y + height / 2;

    return (
      <motion.rect
        animate={controls}
        fill={finalColors.feature}
        height={Math.max(height, 0.5)}
        initial={{ scaleY: 1 }}
        // A capsule at any height: at full height this is a rounded bar, and as
        // the eye shuts the radius follows it down into a lozenge instead of
        // squashing a fixed corner into a rectangle.
        rx={Math.min(EYE_RADIUS * shape.w, Math.max(height, 0.5) / 2)}
        style={{
          rotate: shape.rotate ?? 0,
          transformOrigin: `${cx}px ${cy}px`,
          x: gazeX,
          y: gazeY,
        }}
        transition={
          shouldReduceMotion
            ? { duration: 0 }
            : { bounce: 0.1, duration: 0.25, type: "spring" }
        }
        width={width}
        x={x}
        y={y}
      />
    );
  };

  const renderDizzyEye = (side: -1 | 1) => (
    <motion.path
      animate={shouldReduceMotion ? undefined : { rotate: 360 * side }}
      d={SPIRAL}
      fill="none"
      stroke={finalColors.feature}
      strokeLinecap="round"
      strokeWidth={3}
      style={{
        scale: 1.5,
        x: CENTER + side * EYE_OFFSET,
        y: EYE_Y + EYE_HEIGHT / 2,
      }}
      transition={{
        duration: 2.4,
        ease: EASE_LINEAR,
        repeat: Number.POSITIVE_INFINITY,
      }}
    />
  );

  // Orb draws its sphere at 86% of its own box, so the box is scaled up by
  // that much to land the sphere exactly on the r=48 circle the face was drawn
  // around. Both layers carry the same controls, so it breathes as one object.
  const bodySpan = (96 / VIEWBOX / ORB_SPHERE_FRACTION) * 100;
  const bodyInset = (100 - bodySpan) / 2;

  return (
    <div
      className={cn("relative block", className)}
      style={{
        filter: `saturate(${stateMotion.saturation})`,
        height: resolvedSize,
        width: resolvedSize,
      }}
    >
      <motion.div
        animate={bodyControls}
        className="absolute"
        style={{
          height: `${bodySpan}%`,
          left: `${bodyInset}%`,
          top: `${bodyInset}%`,
          width: `${bodySpan}%`,
        }}
      >
        {/* Painted understudy for the shader: on pages running many WebGL
            surfaces the browser reclaims the oldest contexts, and a reclaimed
            Orb leaves a blank canvas, which turned the character into a pair
            of floating eyes. This circle sits exactly under the sphere so the
            body survives losing its context. */}
        <div
          aria-hidden
          className="absolute rounded-full"
          style={{
            background: `radial-gradient(circle at 34% 30%, ${finalColors.bodyEdge}, ${finalColors.body} 72%)`,
            inset: `${(1 - ORB_SPHERE_FRACTION) * 50}%`,
          }}
        />
        <Orb
          className="size-full"
          colors={[finalColors.body, finalColors.bodyEdge]}
          // Speaking stirs the interior, so the character looks like it is
          // doing something inside rather than only changing size.
          flow={0.6 + energy * 0.36}
          // The halo would spill past the silhouette the features sit against.
          glow={0}
          size="100%"
          turbulence={0.4 + energy * 0.32}
        />
      </motion.div>
      <motion.svg
        animate={bodyControls}
        aria-hidden={ariaLabel ? undefined : true}
        aria-label={ariaLabel}
        className="absolute inset-0 block size-full overflow-visible"
        ref={svgRef}
        role={ariaLabel ? "img" : undefined}
        viewBox={`0 0 ${VIEWBOX} ${VIEWBOX}`}
      >
        <title>{ariaLabel ?? "AI assistant character"}</title>

        {isBroken ? null : renderEye(-1)}
        {isBroken ? null : renderEye(1)}
        {isBroken && renderDizzyEye(-1)}
        {isBroken && renderDizzyEye(1)}
      </motion.svg>
    </div>
  );
};

export default AIOrbFace;

"use client";

import { cn } from "@/lib/utils";
import { useEffect, useRef, useState } from "react";

/**
 * A configurable WebGL2 orb: a lit sphere with colour marbling inside it.
 *
 * Two ideas carry the whole thing.
 *
 * The loop is seamless by construction, not by crossfade. Every point walks a
 * circle in a flow field whose angle advances by exactly one turn per loop, so
 * the displacement returns to where it started. Neighbouring points begin at
 * different angles, and that is what reads as swirling: offset the whole
 * domain by one shared vector instead and you get a pulse.
 *
 * Colour is mixed in OkLab. The midpoint between two stops stays clean instead
 * of going muddy through sRGB, each picked colour reproduces exactly at its own
 * stop, and the hue ripple is a real rotation in the a/b plane.
 *
 * Everything else is lighting on a sphere impostor: the normal is derived per
 * pixel from the distance to the centre, which is what lets a rim, a highlight
 * and a shaded side exist at all. A radial gradient has no surface, and that is
 * the entire difference between this and a coloured circle.
 *
 * Contains two public-domain pieces of prior art, marked at their definitions:
 * the MurmurHash3 finalizer (Austin Appleby) and the OkLab transform matrices
 * (Björn Ottosson).
 */

export interface OrbProps {
  /**
   * Rim dispersion. Splits the palette lookup per channel toward the edge, the
   * way a lens fringes.
   */
  aberration?: number;
  /** Which colour dominates. `0.5` is even; below favours the first stop. */
  balance?: number;
  /** Interior cell size. Small is busy, large is one slow swell. */
  blobScale?: number;
  /** Hue ripple through the palette. */
  chroma?: number;
  className?: string;
  /** Two to four stops. Two read as a material, four as iridescent. */
  colors?: string[];
  /** Lightness contrast around the midpoint. */
  contrast?: number;
  /** Seconds for one full, seamless loop. */
  duration?: number;
  /** How far the flow field carries the field over a loop. */
  flow?: number;
  /** A halo cast outside the silhouette. `0` is none. */
  glow?: number;
  /** Film grain. Also hides the banding large soft gradients show. */
  grain?: number;
  /** Internal scatter, offset away from the highlight. Fake subsurface. */
  inner?: number;
  /** Fresnel-driven hue rotation: thin-film sheen. */
  iridescence?: number;
  /** Light direction, x. */
  lightX?: number;
  /** Light direction, y. */
  lightY?: number;
  /** Freeze on the current frame. */
  paused?: boolean;
  /** Bends the noise lookup by the surface normal. */
  refraction?: number;
  /** Fresnel edge brightness. This is what reads as glass. */
  rim?: number;
  /** Blends the palette toward plain diffuse shading. */
  shading?: number;
  /** Rotates the palette. */
  shift?: number;
  /** Rendered size. Numbers are pixels. */
  size?: number | string;
  /** Edge feather. `0` still resolves to about 1.5 device pixels. */
  softness?: number;
  /** Specular highlight strength. */
  specular?: number;
  /** Strength of the second, nested warp: marbling rather than blobs. */
  turbulence?: number;
  /** Silhouette deformation, so the orb is a drop rather than a ball. */
  wobble?: number;
}

/** The editor's own defaults, which are a good orb rather than a neutral one. */
const DEFAULTS = {
  aberration: 0.8,
  balance: 0.5,
  blobScale: 3,
  chroma: 1,
  colors: ["#f25aed", "#ffffff"],
  contrast: 1,
  duration: 7,
  flow: 0.6,
  glow: 0,
  grain: 0.6,
  inner: 0.38,
  iridescence: 0,
  lightX: -0.6,
  lightY: -1,
  refraction: 0.25,
  rim: 1.3,
  shading: 0.05,
  shift: 0.23,
  softness: 0.005,
  specular: 0.2,
  turbulence: 0.4,
  wobble: 0,
} as const;

const MAX_STOPS = 4;
const MAX_DPR = 2;
const RGB_MAX = 255;
const SRGB_KNEE = 0.040_45;
const TAU = Math.PI * 2;
/** Ambient motion gains nothing from 120 Hz. */
const FRAME_CAP_MS = 1000 / 60;
const LIGHT_Z = 0.65;
const BALANCE_BASE = 5;
/** Keeps rendering slightly before the orb scrolls into view. */
const ROOT_MARGIN = "120px";

/* The covering triangle is built from gl_VertexID, so there is no vertex
   buffer and no attribute state to manage. */
const VERTEX = `#version 300 es
void main() {
  vec2 p = vec2(float((gl_VertexID << 1) & 2), float(gl_VertexID & 2));
  gl_Position = vec4(p * 2.0 - 1.0, 0.0, 1.0);
}`;

const FRAGMENT = `#version 300 es
precision highp float;
precision highp int;   // the hash needs full 32-bit ints

uniform vec2  uRes;
uniform float uPhase;
uniform vec3  uLab[4];
uniform float uCount;
uniform float uScaleN;
uniform float uFlow;
uniform float uTurb;
uniform float uShift;
uniform float uBalance;
uniform float uChroma;
uniform float uContrast;
uniform float uRim;
uniform float uSpec;
uniform float uInner;
uniform float uShading;
uniform float uRefract;
uniform float uIrid;
uniform float uAberr;
uniform float uGrain;
uniform float uSoft;
uniform float uWobble;
uniform float uGlow;
uniform vec3  uLight;

out vec4 fragColor;

const float TAU = 6.28318530718;
const float RAD = 0.86;         // sphere radius in uv units; the rest is glow room
const float RMAX = 1.0 / RAD;   // radius reached at the nearest canvas edge

/* MurmurHash3 finalizer, Austin Appleby, public domain. Exact at any lattice
   coordinate, so unlike a fract(sin(...)) hash it never bands as the input
   grows, which matters for the grain, whose input runs into the thousands. */
uint hashU(uint x) {
  x ^= x >> 16; x *= 0x85EBCA6Bu;
  x ^= x >> 13; x *= 0xC2B2AE35u;
  x ^= x >> 16;
  return x;
}
uint hashU2(uvec2 p) { return hashU(p.x * 0x9E3779B9u ^ hashU(p.y)); }
uint hashU3(uvec3 p) { return hashU(p.x * 0x9E3779B9u ^ hashU(p.y) ^ hashU(p.z) * 0x27D4EB2Fu); }
float rand2(ivec2 p) { return float(hashU2(uvec2(p + 4096)) >> 8) / 16777216.0; }
float rand3(ivec3 p) { return float(hashU3(uvec3(p + 4096)) >> 8) / 16777216.0; }

float vnoise(vec2 p) {
  ivec2 i = ivec2(floor(p));
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(rand2(i),               rand2(i + ivec2(1, 0)), u.x),
             mix(rand2(i + ivec2(0, 1)), rand2(i + ivec2(1, 1)), u.x), u.y);
}

float fbm(vec2 p) {
  float s = 0.0, a = 0.5;
  for (int k = 0; k < 3; k++) { s += a * vnoise(p); p *= 2.03; a *= 0.5; }
  return s / 0.875;
}

/* Each point walks its own circle, completing exactly one turn per loop. */
vec2 flowField(vec2 p) {
  float ang = TAU * vnoise(p + 11.3) + uPhase;
  float mag = 0.35 + 0.65 * vnoise(p + 27.9);
  return vec2(cos(ang), sin(ang)) * mag;
}

/* Fresnel-driven hue rotation in the a/b plane: thin-film sheen. */
vec3 iridesce(vec3 lab, float f) {
  float a = uIrid * f * -2.2;
  float c = cos(a), s = sin(a);
  return vec3(lab.x, c * lab.y - s * lab.z, s * lab.y + c * lab.z);
}

vec3 labRamp(float x) {
  float xx = clamp(x, 0.0, 1.0) * (uCount - 1.0);
  vec3 c = mix(uLab[0], uLab[1], clamp(xx, 0.0, 1.0));
  c = mix(c, uLab[2], clamp(xx - 1.0, 0.0, 1.0));
  c = mix(c, uLab[3], clamp(xx - 2.0, 0.0, 1.0));
  return c;
}

vec3 paletteLab(float t) {
  float x = pow(clamp(0.5 + 0.5 * cos(TAU * t), 0.0, 1.0), uBalance);
  vec3 lab = labRamp(x);
  float ang = TAU * (t * 2.0 + 0.123);
  lab.yz += 0.17 * uChroma * length(lab.yz) * vec2(sin(ang), cos(ang * 1.37 + 1.1));
  /* Cap to roughly the sRGB chroma ceiling. Scaling a/b keeps the hue angle;
     overshooting and clamping RGB later posterises into flat patches. */
  float ch = length(lab.yz);
  if (ch > 0.33) { lab.yz *= 0.33 / ch; }
  lab.x = clamp(0.5 + (lab.x - 0.5) * uContrast, 0.0, 1.0);
  return lab;
}

/* OkLab transform, Björn Ottosson, public domain. */
vec3 oklabToLinear(vec3 c) {
  float l_ = c.x + 0.3963377774 * c.y + 0.2158037573 * c.z;
  float m_ = c.x - 0.1055613458 * c.y - 0.0638541728 * c.z;
  float s_ = c.x - 0.0894841775 * c.y - 1.2914855480 * c.z;
  vec3 lms = vec3(l_ * l_ * l_, m_ * m_ * m_, s_ * s_ * s_);
  return mat3( 4.0767416621, -1.2684380046, -0.0041960863,
              -3.3077115913,  2.6097574011, -0.7034186147,
               0.2309699292, -0.3413193965,  1.7076147010) * lms;
}

vec3 linearToSrgb(vec3 c) {
  c = clamp(c, 0.0, 1.0);
  vec3 lo = c * 12.92;
  vec3 hi = 1.055 * pow(max(c, 1e-5), vec3(1.0 / 2.4)) - 0.055;
  return mix(lo, hi, step(0.0031308, c));
}

void main() {
  vec2 uv = (gl_FragCoord.xy * 2.0 - uRes) / min(uRes.x, uRes.y);
  uv /= RAD;

  /* Silhouette wobble. Integer harmonics of the angle keep it continuous all
     the way round; integer multiples of the phase keep it periodic in time.
     Faded in with radius so the rim deforms like a drop while the core stays
     put, which also keeps it away from atan()'s singularity at the centre. */
  if (uWobble > 0.0) {
    float r0 = length(uv);
    float th = atan(uv.y, uv.x + 1e-6);
    float wob = 0.60 * sin(3.0 * th + uPhase)
              + 0.40 * sin(5.0 * th - 2.0 * uPhase)
              + 0.25 * sin(7.0 * th + 3.0 * uPhase);
    uv *= 1.0 - uWobble * 0.055 * wob * smoothstep(0.0, 0.5, r0);
  }

  float r = length(uv);
  vec2 pd = uv / max(r, 1.0);
  float z = sqrt(max(1.0 - dot(pd, pd), 0.0));
  vec3 n = vec3(pd, z);

  /* Domain warping. The base fBm is static; all the motion comes from warping
     its input through the looping flow field, and nesting a second warp is
     what turns smooth blobs into marbled, ink-in-water flow. */
  vec2 p0 = (pd - n.xy * uRefract) * uScaleN;
  vec2 p1 = p0 + uFlow * flowField(p0);
  vec2 p2 = p1 + uTurb * flowField(p1 * 1.7 + 5.2);
  float t = mix(0.5, fbm(p2 + 3.7), 1.35) + uShift;

  float fres3 = pow(1.0 - n.z, 3.0);
  vec3 lab = iridesce(paletteLab(t), fres3);

  vec3 base;
  if (uAberr > 0.001) {
    // Dispersion: the palette lookup shifts per channel, strongest at the rim.
    float d = uAberr * 0.05 * r * r;
    base = vec3(oklabToLinear(iridesce(paletteLab(t - d), fres3)).r,
                oklabToLinear(lab).g,
                oklabToLinear(iridesce(paletteLab(t + d), fres3)).b);
  } else {
    base = oklabToLinear(lab);
  }
  base = max(base, 0.0);

  // Lighting is added in linear light, which is where it belongs.
  vec3 L = normalize(uLight);
  vec3 col = mix(base, vec3(clamp(dot(n, L), 0.0, 1.0)), uShading);

  // Internal scatter offset away from the highlight: a translucent body rather
  // than a lit opaque ball.
  vec2 op = pd + L.xy * 0.45;
  col += uInner * exp(-dot(op, op) * 2.2) * base;

  vec3 half_ = normalize(L + vec3(0.0, 0.0, 1.0));
  col += pow(1.0 - n.z, 8.0) * uRim
       + pow(max(dot(n, half_), 0.0), 24.3) * uSpec;

  vec3 lit = linearToSrgb(col);
  vec3 flat_ = linearToSrgb(base);

  // Never thinner than ~1.5 device px, so the rim stays smooth when the
  // character is rendered small.
  float w = max(uSoft, 1.5 * fwidth(r));
  float body = 1.0 - smoothstep(1.0 - w, 1.0, r);

  /* The halo has to reach exactly zero before the canvas boundary. Left alone
     it is still ~1.5/255 at the edge and gets cut off square, which shows the
     canvas box as a faint rectangle around the orb. */
  float glowF = uGlow * exp(-max(r - 1.0, 0.0) * 20.0);
  glowF *= 1.0 - smoothstep(0.45, 1.0, (r - 1.0) / (RMAX - 1.0));
  float alpha = clamp(body + glowF * (1.0 - body), 0.0, 1.0);

  vec3 outCol = mix(flat_, lit, body);

  // Grain plus an always-on deband dither, stepped to 24 frames per loop so it
  // animates without breaking the seam.
  int frame = int(uPhase / TAU * 24.0);
  outCol += (rand3(ivec3(ivec2(gl_FragCoord.xy), frame)) - 0.5)
          * (uGrain * 0.1 + 1.0 / 255.0);

  outCol = clamp(outCol, 0.0, 1.0);
  fragColor = vec4(outCol * alpha, alpha);   // premultiplied
}`;

/**
 * Any CSS colour to OkLab, in two steps because neither alone is enough.
 *
 * `getComputedStyle` resolves `var()` and named colours, but Chrome hands back
 * `oklch(0.72 0.21 322)` verbatim rather than converting it: read that as three
 * sRGB channels and a magenta comes out blue. A 1x1 2D canvas rasterises
 * whatever syntax survives into actual pixels, which is the only step that
 * cannot lie about the result.
 */
const cssToOklab = (input: string): [number, number, number] => {
  const probe = document.createElement("span");
  probe.style.color = input;
  document.body.appendChild(probe);
  const resolved = getComputedStyle(probe).color;
  probe.remove();

  const surface = document.createElement("canvas");
  surface.width = 1;
  surface.height = 1;
  const ctx = surface.getContext("2d", { willReadFrequently: true });
  if (!ctx) {
    return [1, 0, 0];
  }
  ctx.fillStyle = resolved;
  ctx.fillRect(0, 0, 1, 1);
  const [r8, g8, b8] = ctx.getImageData(0, 0, 1, 1).data;

  // biome-ignore-start lint/style/useNumericSeparators: published colour-space constants, kept digit-for-digit against the reference
  const [r, g, b] = [r8, g8, b8].map((channel) => {
    const u = channel / RGB_MAX;
    return u <= SRGB_KNEE ? u / 12.92 : ((u + 0.055) / 1.055) ** 2.4;
  });
  const l = Math.cbrt(0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b);
  const m = Math.cbrt(0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b);
  const s = Math.cbrt(0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b);
  return [
    0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s,
    1.9779984951 * l - 2.428592205 * m + 0.4505937099 * s,
    0.0259040371 * l + 0.7827717662 * m - 0.808675766 * s,
  ];
  // biome-ignore-end lint/style/useNumericSeparators: published colour-space constants
};

const compileShader = (
  gl: WebGL2RenderingContext,
  type: number,
  source: string
) => {
  const shader = gl.createShader(type);
  if (!shader) {
    return null;
  }
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    gl.deleteShader(shader);
    return null;
  }
  return shader;
};

export default function Orb({ className, size = 240, ...rest }: OrbProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  // The fallback lives here rather than in the caller: a stand-in drawn by
  // whoever embeds the orb ends up painted over the canvas, which hides the
  // real thing on every machine that can render it.
  const [supported, setSupported] = useState(true);

  // Read inside the loop rather than closed over, so turning a knob pushes a
  // uniform instead of tearing down and rebuilding the GL context.
  const syncConfig = useRef<(() => void) | null>(null);
  const config = useRef({ ...DEFAULTS, ...rest });
  config.current = { ...DEFAULTS, ...rest };

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) {
      return;
    }
    const gl = canvas.getContext("webgl2", {
      alpha: true,
      antialias: false, // a covering triangle has no geometric edges to sample
      depth: false,
      powerPreference: "low-power",
      premultipliedAlpha: true,
      stencil: false,
    });
    if (!gl) {
      setSupported(false);
      return;
    }

    const vs = compileShader(gl, gl.VERTEX_SHADER, VERTEX);
    const fs = compileShader(gl, gl.FRAGMENT_SHADER, FRAGMENT);
    const program = gl.createProgram();
    if (!(vs && fs && program)) {
      setSupported(false);
      return;
    }
    gl.attachShader(program, vs);
    gl.attachShader(program, fs);
    gl.linkProgram(program);
    gl.deleteShader(vs);
    gl.deleteShader(fs);
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
      setSupported(false);
      return;
    }
    // biome-ignore lint/correctness/useHookAtTopLevel: WebGL2RenderingContext.useProgram is not a React hook.
    gl.useProgram(program);
    // Recoverable: a failed first attempt must not disable the orb forever.
    setSupported(true);
    gl.disable(gl.DEPTH_TEST);
    gl.disable(gl.BLEND); // the shader writes premultiplied RGBA straight out

    const at = (name: string) => gl.getUniformLocation(program, name);
    const u = {
      aberr: at("uAberr"),
      balance: at("uBalance"),
      chroma: at("uChroma"),
      contrast: at("uContrast"),
      count: at("uCount"),
      flow: at("uFlow"),
      glow: at("uGlow"),
      grain: at("uGrain"),
      inner: at("uInner"),
      irid: at("uIrid"),
      lab: at("uLab"),
      light: at("uLight"),
      phase: at("uPhase"),
      refract: at("uRefract"),
      res: at("uRes"),
      rim: at("uRim"),
      scaleN: at("uScaleN"),
      shading: at("uShading"),
      shift: at("uShift"),
      soft: at("uSoft"),
      spec: at("uSpec"),
      turb: at("uTurb"),
    };

    const pushConfig = () => {
      const c = config.current;
      const stops = c.colors.slice(0, MAX_STOPS);
      const lab = new Float32Array(MAX_STOPS * 3);
      for (let i = 0; i < MAX_STOPS; i++) {
        const [x, y, z] = cssToOklab(stops[Math.min(i, stops.length - 1)]);
        lab[i * 3] = x;
        lab[i * 3 + 1] = y;
        lab[i * 3 + 2] = z;
      }
      gl.uniform3fv(u.lab, lab);
      gl.uniform1f(u.count, Math.max(2, Math.min(stops.length, MAX_STOPS)));
      // The prop reads as blob size, so invert it into cell frequency.
      gl.uniform1f(u.scaleN, 1.45 / Math.max(c.blobScale, 0.05));
      gl.uniform1f(u.flow, c.flow);
      gl.uniform1f(u.turb, c.turbulence);
      gl.uniform1f(u.shift, c.shift);
      gl.uniform1f(u.balance, BALANCE_BASE ** ((0.5 - c.balance) * 2));
      gl.uniform1f(u.chroma, c.chroma);
      gl.uniform1f(u.contrast, c.contrast);
      gl.uniform1f(u.rim, c.rim);
      gl.uniform1f(u.spec, c.specular);
      gl.uniform1f(u.inner, c.inner);
      gl.uniform1f(u.shading, c.shading);
      gl.uniform1f(u.refract, c.refraction);
      gl.uniform1f(u.irid, c.iridescence);
      gl.uniform1f(u.aberr, c.aberration);
      gl.uniform1f(u.grain, c.grain);
      gl.uniform1f(u.soft, c.softness);
      gl.uniform1f(at("uWobble"), c.wobble);
      gl.uniform1f(u.glow, c.glow);
      gl.uniform3f(u.light, c.lightX, c.lightY, LIGHT_Z);
    };

    const resize = (entry?: ResizeObserverEntry) => {
      const box = entry?.devicePixelContentBoxSize;
      let w: number;
      let h: number;
      if (box?.length) {
        w = box[0].inlineSize;
        h = box[0].blockSize;
      } else {
        const dpr = Math.min(window.devicePixelRatio || 1, MAX_DPR);
        const rect = canvas.getBoundingClientRect();
        w = Math.round(rect.width * dpr);
        h = Math.round(rect.height * dpr);
      }
      w = Math.max(1, w);
      h = Math.max(1, h);
      if (canvas.width === w && canvas.height === h) {
        return false;
      }
      canvas.width = w;
      canvas.height = h;
      gl.viewport(0, 0, w, h);
      gl.uniform2f(u.res, w, h);
      return true;
    };

    const draw = () => {
      gl.clearColor(0, 0, 0, 0);
      gl.clear(gl.COLOR_BUFFER_BIT);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
    };

    let phase = 0;
    let pending = 0;
    let last = 0;
    let raf = 0;
    let running = false;
    let onScreen = true;
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)");

    const tick = (now: number) => {
      raf = requestAnimationFrame(tick);
      const dt = last ? Math.min(now - last, 100) : FRAME_CAP_MS;
      last = now;
      pending += dt;
      /* Half a frame of slack: without it, a display whose vsync divides the
         cap almost exactly drops an extra frame and the cadence stutters. */
      if (pending < FRAME_CAP_MS - dt * 0.5) {
        return;
      }
      phase = (phase + pending / 1000 / config.current.duration) % 1;
      pending = 0;
      gl.uniform1f(u.phase, phase * TAU);
      draw();
    };

    const start = () => {
      if (running || reduce.matches || config.current.paused || !onScreen) {
        return;
      }
      running = true;
      last = 0;
      pending = 0;
      raf = requestAnimationFrame(tick);
    };

    const stop = () => {
      running = false;
      if (raf) {
        cancelAnimationFrame(raf);
      }
      raf = 0;
    };

    const applyMotionPreference = () => {
      if (reduce.matches || config.current.paused) {
        stop();
        if (reduce.matches) {
          gl.uniform1f(u.phase, 0);
        }
        draw();
        return;
      }
      start();
    };

    syncConfig.current = () => {
      pushConfig();
      applyMotionPreference();
      if (!running) {
        draw();
      }
    };

    pushConfig();
    resize();
    gl.uniform1f(u.phase, 0);
    draw();

    const observer = new ResizeObserver((entries) => {
      if (resize(entries[0]) && !running) {
        draw();
      }
    });
    try {
      observer.observe(canvas, { box: "device-pixel-content-box" });
    } catch {
      observer.observe(canvas);
    }

    /* Scrolled out of view is the common case. Nothing is gained by burning
       GPU on an orb nobody can see. */
    const seen = new IntersectionObserver(
      (entries) => {
        onScreen = entries.at(-1)?.isIntersecting ?? true;
        if (onScreen) {
          start();
        } else {
          stop();
        }
      },
      { rootMargin: ROOT_MARGIN }
    );
    seen.observe(canvas);

    reduce.addEventListener("change", applyMotionPreference);
    applyMotionPreference();

    return () => {
      syncConfig.current = null;
      stop();
      observer.disconnect();
      seen.disconnect();
      reduce.removeEventListener("change", applyMotionPreference);
      gl.deleteProgram(program);
      /* Deliberately NOT calling WEBGL_lose_context here. React remounts
         effects in development, and the second pass gets the same canvas back
         with a context that is still lost: the program then fails to link and
         the component latches into its fallback for good. Dropping the canvas
         is enough; the context goes with it. */
    };
  }, []);

  // Synchronize committed props even when animation is paused or reduced.
  // Keep the GPU resources stable; never convert colors on every frame.
  useEffect(() => {
    syncConfig.current?.();
  });

  const dimension = typeof size === "number" ? `${size}px` : size;

  if (!supported) {
    const stops = (rest.colors ?? DEFAULTS.colors).slice(0, MAX_STOPS);
    return (
      <div
        aria-hidden="true"
        className={cn("block rounded-full", className)}
        style={{
          // Lit from the same corner as the shader, so the character does not
          // change which way it faces when it falls back.
          backgroundImage: `radial-gradient(circle at 32% 28%, ${stops.join(", ")})`,
          height: dimension,
          width: dimension,
        }}
      />
    );
  }

  return (
    <canvas
      aria-hidden="true"
      className={cn("block", className)}
      ref={canvasRef}
      style={{ height: dimension, width: dimension }}
      tabIndex={-1}
    />
  );
}

"use client";

import {
  type MotionValue,
  useAnimationFrame,
  useMotionValue,
